sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {

   if (isLoading || newValue === '') {
      return;
   }
   //Checks if user has role itil
   var isItil = g_user.hasRole('itil');
   //if new state is canceled and user has itil role
   if (newValue === '8' && isItil){
	alert("An itil role cant set state to cancelled, please select another state.");
	//Sets state value back to default
	g_form.clearValue('state');
   }

}
